        for (let c = 0; c <= W; c++) {
            const h = c === W ? 0 : heights[c];
            while (top > 0 && heights[stack[top - 1]] >= h) {
                const height = heights[stack[--top]];
                if (height > 0) {
                    const width = top === 0 ? c : c - stack[top - 1] - 1;
                    const area = (height + 1) * (width + 1);
                    if (area > maxArea) {
                        maxArea = area;
                    }
                }
            }
            stack[top++] = c;
        }
